function getUser(db, username, password) {
    return new Promise((resolve) => {
        const query = 'SELECT userInfo FROM users WHERE username = ? AND password = ?';
        db.get(query, [username, password], (err, row) => {
            if (err) {
                resolve(null);
            } else {
                resolve(row ? row.userInfo : null);
            }
        });
    });
}
